pub fn is_reserved_name(id: &str) -> bool {
    let name = id.trim_start_matches('/');
    BUILTIN_COMMANDS
        .iter()
        .any(|b| b.eq_ignore_ascii_case(name))
}

/// Project root down to the current directory, so nested `.claude`/`.agents`
/// skill folders are found in the documented order.
fn ancestor_dirs(root: &Path) -> Vec<PathBuf> {
    let mut dirs = vec![root.to_path_buf()];
    if let Ok(cwd) = std::env::current_dir()
        && let Ok(rel) = cwd.strip_prefix(root)
    {
        let mut cur = root.to_path_buf();
        for comp in rel.components() {
            cur = cur.join(comp);
            dirs.push(cur.clone());
        }
    }
    dirs
}

/// Discover skills, including extra directories named by `config.skills`.
/// Later sources replace earlier ones with the same id.
pub fn discover_with(project_root: &Path, extra: &[String]) -> Vec<Skill> {
    let home = home_base();
    // `true` marks project-scoped roots (ancestor dirs, `extra`); `false`
    // marks global roots. A project skill keeps winning over a global skill
    // with the same id, but the winner is flagged via `Skill::shadowed`.
    let mut roots: Vec<(PathBuf, bool)> = Vec::new();
    // Built-in skills: none packaged yet.
    if let Some(home) = &home {
        roots.push((home.join(".claude").join("skills"), false));
    }
    for dir in ancestor_dirs(project_root) {
        roots.push((dir.join(".claude").join("skills"), true));
    }
    if let Some(home) = &home {
        roots.push((home.join(".agents").join("skills"), false));
    }
    for dir in ancestor_dirs(project_root) {
        roots.push((dir.join(".agents").join("skills"), true));
    }
    if let Some(home) = &home {
        roots.push((home.join(".config").join("freedas").join("skills"), false));
    }
    for dir in ancestor_dirs(project_root) {
        roots.push((dir.join(".freedas").join("skills"), true));
    }
    for dir in extra {
        let dir = if Path::new(dir).is_absolute() {
            PathBuf::from(dir)
        } else {
            project_root.join(dir)
        };
        roots.push((dir, true));
    }
    let mut skills: Vec<Skill> = Vec::new();
    let mut project_scoped: Vec<bool> = Vec::new();
    for (root, is_project) in roots {
        if !root.exists() {
            continue;
        }
        // Root-level `*.md` files are one-file skills named by their stem.
        if let Ok(entries) = std::fs::read_dir(&root) {
            for entry in entries.flatten() {
                let Ok(ft) = entry.file_type() else {
                    continue;
                };
                let path = entry.path();
                let is_flat_md = ft.is_file()
                    && path.extension().map(|e| e == "md").unwrap_or(false)
                    && path.file_name().map(|n| n != "SKILL.md").unwrap_or(true)
                    && !path
                        .file_name()
                        .map(|n| n.to_string_lossy().starts_with('.'))
                        .unwrap_or(false);
                if !is_flat_md {
                    continue;
                }
                let id = path
                    .file_stem()
                    .map(|s| s.to_string_lossy().to_string())
                    .unwrap_or_default();
                if let Some(skill) = parse_skill_file(&path, id) {
                    if is_reserved_name(&skill.id) {
                        continue;
                    }
                    upsert(&mut skills, &mut project_scoped, skill, is_project);
                }
            }
        }
        for entry in walk(&root, 0) {
            // A skill is a folder with a SKILL.md; other .md files are its
            // reference material, not skills.
            if entry.file_name().map(|n| n == "SKILL.md").unwrap_or(false) {
                let id = entry
                    .parent()
                    .and_then(|p| p.file_name())
                    .map(|s| s.to_string_lossy().to_string())
                    .unwrap_or_else(|| "skill".into());
                if let Some(skill) = parse_skill_file(&entry, id) {
                    if is_reserved_name(&skill.id) {
                        continue;
                    }
                    upsert(&mut skills, &mut project_scoped, skill, is_project);
                }
            }
        }
    }
    skills
}

fn upsert(skills: &mut Vec<Skill>, origins: &mut Vec<bool>, mut skill: Skill, is_project: bool) {
    if let Some(pos) = skills.iter().position(|x| x.id == skill.id) {
        let was_project = origins.remove(pos);
        let old = skills.remove(pos);
        if old.body == skill.body && old.description == skill.description {
            skill.shadowed = old.shadowed;
        } else if is_project && (!was_project || old.shadowed) {
            skill.shadowed = true;
        }
        skills.push(skill);
        origins.push(is_project);
    } else {
        skills.push(skill);
        origins.push(is_project);
    }
}

fn walk(dir: &Path, depth: usize) -> Vec<PathBuf> {
    if depth > 6 {
        return Vec::new();
    }
    let mut out = Vec::new();
    if let Ok(entries) = std::fs::read_dir(dir) {
        for e in entries.flatten() {
            let Ok(ft) = e.file_type() else {
                continue;
            };
            let p = e.path();
            if ft.is_dir() {
                if p.file_name()
                    .map(|n| n.to_string_lossy().starts_with('.') || n == "node_modules")
                    .unwrap_or(false)
                {
                    continue;
                }
                out.extend(walk(&p, depth + 1));
            } else if ft.is_file() {
                out.push(p);
            }
            // Symlinks and other non-regular files are ignored, matching the
            // agent walker: never follow a link out of the skills tree.
        }
    }
    out
}

pub fn find<'a>(skills: &'a [Skill], id: &str) -> Option<&'a Skill> {
    skills.iter().find(|s| s.id == id)
}

#[derive(Debug, Clone)]
pub struct Command {
    pub name: String,
    pub description: String,
    pub agent: Option<String>,
    pub model: Option<String>,
    pub subtask: bool,
    pub body: String,
}

/// Load `.freedas/commands/*.md` and `~/.config/freedas/commands/*.md`.
/// A later source with the same name replaces the earlier one.
pub fn discover_commands(project_root: &Path) -> Vec<Command> {
    let mut dirs = Vec::new();
    if let Some(home) = home_base() {
        dirs.push(home.join(".config").join("freedas").join("commands"));
    }
    dirs.push(project_root.join(".freedas").join("commands"));
    let mut commands: Vec<Command> = Vec::new();
    for dir in dirs {
        let Ok(entries) = std::fs::read_dir(&dir) else {
            continue;
        };
        for entry in entries.flatten() {
            let p = entry.path();
            if p.extension().map(|x| x != "md").unwrap_or(true) {
                continue;
            }
            let Some(name) = p.file_stem().map(|s| s.to_string_lossy().to_string()) else {
                continue;
            };
            if is_reserved_name(&name) {
                continue;
            }
            let text = std::fs::read_to_string(&p).unwrap_or_default();
            let (front, body) = freedas_agent::parse_frontmatter(&text)
                .unwrap_or((serde_json::json!({}), text.clone()));
            let command = Command {
                name: name.clone(),
                description: front["description"].as_str().unwrap_or("").to_string(),
                agent: front["agent"].as_str().map(|s| s.to_string()),
                model: front["model"].as_str().map(|s| s.to_string()),
                subtask: front["subtask"].as_bool().unwrap_or(false),
                body,
            };
            commands.retain(|c| c.name != name);
            commands.push(command);
        }
    }
    commands
}

pub fn expand_args(body: &str, args: &str) -> String {
    let words: Vec<&str> = args.split_whitespace().collect();
    let mut out = String::with_capacity(body.len() + args.len());
    let mut rest = body;
    while let Some(i) = rest.find('$') {
        out.push_str(&rest[..i]);
        let after = &rest[i + 1..];
        // `$$` is a literal `$` and never expands, so `$$ARGUMENTS` stays
        // `$ARGUMENTS` instead of expanding.
        if let Some(stripped) = after.strip_prefix('$') {
            out.push('$');
            rest = stripped;
            continue;
        }
        if let Some(tail) = after.strip_prefix("ARGUMENTS") {
            out.push_str(args);
            rest = tail;
            continue;
        }
        let digits: String = after.chars().take_while(char::is_ascii_digit).collect();
        if digits.is_empty() {
            out.push('$');
            rest = after;
            continue;
        }
        let n: usize = digits.parse().unwrap_or(0);
        match words
            .get(n.wrapping_sub(1))
            .filter(|_| (1..=9).contains(&n))
        {
            // Out-of-range words stay literal so a second pass cannot expand them.
            None => out.push_str(&rest[i..i + 1 + digits.len()]),
            Some(word) => out.push_str(word),
        }
        rest = &after[digits.len()..];
    }
    out.push_str(rest);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn expand() {
        assert_eq!(expand_args("do $ARGUMENTS and $1", "a b"), "do a b and a");
    }

    #[test]
    fn expand_is_single_pass() {
        assert_eq!(expand_args("$ARGUMENTS", "$1"), "$1");
        assert_eq!(expand_args("$1 and $2", "a"), "a and $2");
        assert_eq!(expand_args("pick $10", "a b"), "pick $10");
        assert_eq!(expand_args("$0 stays", "a"), "$0 stays");
    }

    #[test]
    fn flat_skills_and_marker_only() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().join(".freedas").join("skills");
        std::fs::create_dir_all(root.join("auto-manual")).unwrap();
        std::fs::write(
            root.join("release.md"),
            "---\ndescription: Cut a release\n---\nBody",
        )
        .unwrap();
        std::fs::write(
            root.join("auto-manual").join("SKILL.md"),
            "---\nname: auto-manual\ndescription: manual\n---\nBody",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("learned")).unwrap();
        std::fs::write(
            root.join("learned").join("SKILL.md"),
            "---\nname: learned\nmetadata:\n  freedas/autogenerated: true\n---\nBody",
        )
        .unwrap();

        let skills = discover(dir.path());
        let release = find(&skills, "release").expect("flat skill must be discovered");
        assert_eq!(release.description, "Cut a release");
        assert!(!release.autogenerated);
        assert!(!find(&skills, "auto-manual").unwrap().autogenerated);
        assert!(find(&skills, "learned").unwrap().autogenerated);
    }

    #[test]
    fn command_subtask_reads_the_typed_flag() {
        let dir = tempfile::tempdir().unwrap();
        let cmds = dir.path().join(".freedas").join("commands");
        std::fs::create_dir_all(&cmds).unwrap();
        std::fs::write(
            cmds.join("ship.md"),
            "---\ndescription: Ship it\nagent: build\nsubtask: true\n---\nBody",
        )
        .unwrap();
        let found = discover_commands(dir.path());
        let ship = found.iter().find(|c| c.name == "ship").unwrap();
        assert!(ship.subtask, "subtask: true must parse as bool");
        assert_eq!(ship.description, "Ship it");
    }
}
